  {
    "id": "claudinite-website/no-server-behind-the-page",
    "severity": "blocking",
    "since": "2026-09-08",
    "failureMessage": "site/privacy.html tells visitors there is no server of ours behind the page, and a Worker script entry point would make that false with nothing looking wrong",
    "checkParsedFiles": [
      {
        "file": "wrangler.json",
        "forbidField": "main",
        "what": "wrangler.json names a Worker script entry point",
        "fix": "drop \"main\" — claudinite.com is static assets only, and site/privacy.html tells visitors there is no server of ours behind the page; adding one changes that promise and its disclosure first"
      }
    ]
  },
  {
    "id": "claudinite-website/release-contract-carries-its-description",
    "severity": "blocking",
    "since": "2026-09-08",
    "scope": "work",
    "failureMessage": "site/README.md tells the next reader how the site reaches production, and a confident description of a flow that no longer exists is worse than none",
    "requireCoChange": [
      {
        "whenChangedFileMatches": "/^wrangler\\.json$/",
        "requireChangedFileMatching": "/^site\\/README\\.md$/",
        "what": "{path} changes the release contract, and site/README.md did not change with it",
        "fix": "correct the release paragraph in site/README.md in this same commit, or make the change one that leaves the description true"
      }
    ]
  }
]

