ruleTester(checkoutSubmodules, {
  clean: {
    'the checkout step passes submodules: true': { files: { '.gitmodules': GITMODULES, [WF]:
`name: x
on: push
jobs:
  t:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
        with:
