jobs:
  t:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
` } },
  },
  flagged: {
    'a bare checkout, and one whose sibling step carries the key': { files: { '.gitmodules': GITMODULES, [WF]:
